 47	// Cache of namespaced key → display name, populated by views that fetch project data.
 48	// breadcrumb().project() reads from here automatically.
 49	// The cache key is the composite `repo + '/' + slug` to prevent collisions
 50	// between same-slug projects in different repositories.
 51	var ProjectNameCache = (function () {
 52	  var _cache = {};
 53	  return {
 54	    /**
 55	     * Store a display name for a project.
 56	     * @param {string} key  - Namespaced key in the form `repo/slug`.
 57	     *   Legacy callers that have not yet been migrated to the namespaced form (e.g.
 58	     *   `project-detail.js` — see WP-013) may pass a bare slug. Those entries will
 59	     *   not be found by namespaced `get()` calls until the caller is migrated.
 60	     * @param {string} name - Display name to cache.
 61	     */
 62	    set: function (key, name) {
 63	      if (key && name && name.trim()) _cache[key] = name.trim();
 64	    },
 65	    /**
 66	     * Retrieve the display name for a project.
 67	     * @param {string} key - Namespaced key in the form `repo/slug`.
 68	     *   Falsy values (null, undefined, empty string) are handled gracefully: a null/undefined
 69	     *   key returns null without throwing; an empty string key falls through to the slug
 70	     *   extraction path and returns an empty string.
 71	     * @returns {string|null} Cached display name, or the slug portion of the key (after the
 72	     *   last '/') if not found — so breadcrumbs show a readable label before project data is
 73	     *   fetched. Returns null for null/undefined input.
 74	     */
 75	    get: function (key) {
 76	      if (_cache[key]) return _cache[key];
 77	      // Fall back to the slug portion (after the last '/') so breadcrumbs show
 78	      // a readable label even before the project data is fetched.
 79	      var lastSlash = key ? key.lastIndexOf('/') : -1;
 80	      return lastSlash >= 0 ? key.slice(lastSlash + 1) : key;
 81	    },
 82	  };
 83	}());
