 85	function breadcrumb() {
 86	  var segments = [];
 87	  var api = {
 88	    projects: function () {
 89	      segments.push({ label: 'Projects', href: '#/' });
 90	      return api;
 91	    },
 92	    project: function (repo, slug) {
 93	      segments.push({ label: ProjectNameCache.get(repo + '/' + slug), href: '#/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) });
 94	      return api;
 95	    },
 96	    leaf: function (label) {
 97	      segments.push({ label: label });
 98	      return api;
 99	    },
100	    leafSpan: function (label, id) {

101	      segments.push({ label: label, id: id });
102	      return api;
103	    },
104	    html: function () {
105	      return '<p class="breadcrumb">' +
106	        segments.map(function (s) {
107	          if (s.href) return '<a href="' + s.href + '">' + escapeHtml(s.label) + '</a>';
108	          if (s.id)   return '<span id="' + escapeHtml(s.id) + '">' + escapeHtml(s.label) + '</span>';
109	          return escapeHtml(s.label);
110	        }).join(' / ') +
111	        '</p>';
112	    }
113	  };
114	  return api;
115	}
