125	function formatDuration(ms) {
126	  if (ms == null || isNaN(ms) || ms < 0) return '—';
127	  if (ms < 1000) return '< 1s';
128	  var totalSec = Math.floor(ms / 1000);
129	  var hours = Math.floor(totalSec / 3600);
130	  var minutes = Math.floor((totalSec % 3600) / 60);
131	  var seconds = totalSec % 60;
132	  var parts = [];
133	  if (hours > 0) parts.push(hours + 'h');
134	  if (minutes > 0) parts.push(minutes + 'm');
135	  if (seconds > 0 && hours === 0) parts.push(seconds + 's');
136	  return parts.join(' ') || '< 1s';
137	}

